const rawOut = $input.first().json.content || $input.first().json.output || $input.first().json.text || '';
let semantic = 0; try { semantic = Number($('SBERT Score').first().json.hire_score) || 0; } catch (e) {}
const webhookData = $('Webhook').first().json.body;
const webhookBinary = $('Webhook').first().binary;

// Extract the JSON object from the model output (tolerates stray text / markdown).
let parsed = null;
try {
  const m = String(rawOut).replace(/```json|```/g, '').match(/\{[\s\S]*\}/);
  parsed = JSON.parse(m ? m[0] : rawOut);
} catch (e) { parsed = null; }

// Genuine non-resume (short, clean is_resume:false parses fine) -> stop as before.
if (parsed && parsed.is_resume === false) {
  throw new Error("The file does not seem like a resume for our AI and was not parsed.");
}

const p = parsed || {};
const clamp = (n) => Math.min(Math.max(Number(n), 0), 100);
const num = (n) => (isFinite(Number(n)) ? clamp(n) : null);

// LLM judgment: weighted blend of four dimensions (50/30/10/10).
const skills = num(p.skills_match);
const role = num(p.role_relevance);
const impact = num(p.impact);
const soft = num(p.soft_signals);
let llm = null;
if (skills !== null && role !== null && impact !== null && soft !== null) {
  llm = 0.50 * skills + 0.30 * role + 0.10 * impact + 0.10 * soft;
} else if (isFinite(Number(p.hire_score))) {
  llm = clamp(p.hire_score); // tolerate old single-score output format
}

// Dual-model final: LLM judgment (primary) blended with the SBERT semantic signal.
// If the model output was malformed for a REAL resume, fall back to SBERT so it never hard-fails.
let hire;
if (llm !== null) {
  hire = 0.90 * llm + 0.10 * semantic;
} else {
  hire = semantic;
}
hire = Math.round(Math.min(Math.max(hire, 0), 100) * 100) / 100;

return [{
  json: {
    is_resume: p.is_resume !== false,
    applicant_name: p.applicant_name || 'Unknown Applicant',
    applicant_email: p.applicant_email || 'unknown@placeholder.com',
    applicant_phone: p.applicant_phone || null,
    pros: Array.isArray(p.pros) ? p.pros : [],
    cons: Array.isArray(p.cons) ? p.cons : [],
    summary: p.summary || 'Automated evaluation.',
    hire_score: hire,
    semantic_score: semantic,
    skills_match: skills,
    role_relevance: role,
    impact: impact,
    soft_signals: soft,
    requirement_id: webhookData.requirement_id,
    uploaded_by_user_id: webhookData.uploaded_by_user_id || null,
    evaluated_by_user_id: webhookData.evaluated_by_user_id || null,
    job_title: webhookData.job_title,
    description: webhookData.description,
    qualifications: webhookData.qualifications
  },
  binary: webhookBinary
}];

function uuidv4() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    const r = Math.random() * 16 | 0;
    const v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}

const codeData = $('Code in JavaScript').first().json;
const item = $input.first().json;
return [{
  json: {
    ...codeData,
    ...item,
    applicant_id: uuidv4(),
    resume_id: uuidv4(),
    evaluation_id: uuidv4(),
  }
}];

