function uuidv4() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
    const r = Math.random() * 16 | 0;
    return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
  });
}
return $input.all().map(item => ({
  json: { ...item.json, generated_id: uuidv4() }
}));

// OCR.space returns ParsedResults[0].ParsedText; normalize to .text
const r = $input.first().json;
const text = (r.ParsedResults && r.ParsedResults[0] && r.ParsedResults[0].ParsedText) || r.text || '';
return [{ json: { text }, binary: $input.first().binary }];

// === H!RE Score: requirement-coverage matching (Sentence-BERT) ===
// For each job requirement, find the resume's best-matching sentence (max cosine),
// then average that coverage across all requirements and calibrate to 0-100.
// This spreads scores across the full scale far better than whole-doc cosine and
// answers "how much of what the job asks for is actually covered by this resume?".
const CAL_LO = 0.35, CAL_HI = 0.60;      // calibration window — tune against real resumes
const MODEL  = 'sentence-transformers/all-MiniLM-L6-v2';
const MAX_REQ = 12, MAX_CHUNKS = 60, MAX_LEN = 400;

const resumeText = String($input.first().json.text || '');
const body = $('Webhook').first().json.body || {};

const clean = (s) => String(s || '').replace(/\s+/g, ' ').trim();
// Break free text into requirement / sentence units: newlines, bullets, semicolons,
// and sentence-ending punctuation. Keep only units with real content.
const splitUnits = (t) => String(t || '')
  .split(/[\r\n;•·]+|(?<=[.!?])\s+/)
  .map(clean)
  .filter((u) => u.length >= 8 && u.split(' ').length >= 2)
  .map((u) => u.slice(0, MAX_LEN));

// Requirements: qualifications first, then description sentences; prepend the title.
let reqUnits = [...splitUnits(body.qualifications), ...splitUnits(body.description)];
if (body.job_title) reqUnits.unshift(clean(body.job_title).slice(0, MAX_LEN));
reqUnits = [...new Set(reqUnits)].slice(0, MAX_REQ);

// Resume: sentence / line chunks.
let resumeChunks = [...new Set(splitUnits(resumeText))].slice(0, MAX_CHUNKS);

// Fallbacks so we never divide by zero.
if (reqUnits.length === 0)
  reqUnits = [clean(`${body.job_title || ''} ${body.description || ''} ${body.qualifications || ''}`).slice(0, MAX_LEN)];
if (resumeChunks.length === 0)
  resumeChunks = [resumeText.slice(0, MAX_LEN) || ' '];

const cos = (a, b) => { let d = 0, na = 0, nb = 0; for (let i = 0; i < a.length; i++) { d += a[i] * b[i]; na += a[i] * a[i]; nb += b[i] * b[i]; } return d / (Math.sqrt(na) * Math.sqrt(nb) || 1); };
const clamp = (x, lo, hi) => Math.min(Math.max(x, lo), hi);

let hire_score = 0, score_band = 'Unknown', rawCoverage = 0;
try {
  const inputs = [...reqUnits, ...resumeChunks];
  const resp = await this.helpers.httpRequest({
    method: 'POST',
    url: `https://router.huggingface.co/hf-inference/models/${MODEL}/pipeline/feature-extraction`,
    headers: { Authorization: `Bearer ${$env.HF_API_KEY}`, 'Content-Type': 'application/json' },
    body: { inputs, options: { wait_for_model: true } },
    json: true,
  });
  // Mean-pool token embeddings → one vector per input (or use as-is if already pooled).
  const vecs = Array.isArray(resp[0][0])
    ? resp.map((s) => { const d = s[0].length, o = new Array(d).fill(0); s.forEach((t) => t.forEach((x, i) => o[i] += x)); return o.map((x) => x / s.length); })
    : resp;
  const reqVecs = vecs.slice(0, reqUnits.length);
  const resVecs = vecs.slice(reqUnits.length);
  // Coverage: for each requirement, the best-matching resume chunk.
  const coverage = reqVecs.map((rv) => Math.max(...resVecs.map((cv) => cos(rv, cv))));
  rawCoverage = coverage.reduce((a, b) => a + b, 0) / (coverage.length || 1);
  // Calibrate the realistic coverage window onto the full 0-100 scale.
  let cal = rawCoverage;
  if (CAL_HI > CAL_LO) cal = clamp((cal - CAL_LO) / (CAL_HI - CAL_LO), 0, 1);
  hire_score = Math.round(clamp(cal * 100, 0, 100) * 100) / 100;
} catch (err) { hire_score = 0; }

if      (hire_score >= 85) score_band = 'Strong fit';
else if (hire_score >= 65) score_band = 'Good fit, minor gaps';
else if (hire_score >= 50) score_band = 'Moderate fit, notable gaps';
else                       score_band = 'Weak fit';

// raw_coverage is the pre-calibration average (not stored) — shown here only so
// you can read real values in n8n's execution view while tuning CAL_LO / CAL_HI.
return [{ json: { ...$input.first().json, hire_score, score_band, raw_coverage: Math.round(rawCoverage * 1000) / 1000 }, binary: $input.first().binary }];
